/* Player: the cover fills the card's height on the left; title and controls, then volume and the waveform on the right. */
body.player-expanded .player-widget.expanded { position: absolute !important; left: clamp(16px, 3.4vw, 44px); right: clamp(16px, 3.4vw, 44px); bottom: calc(clamp(12px, 4vh, 28px) + var(--car-bar-h, 72px)); top: auto !important; width: auto !important; max-width: none !important; height: clamp(200px, 36vh, 256px) !important; min-height: 0 !important; display: grid !important; grid-template-columns: minmax(150px, 30%) minmax(0, 1fr) auto; grid-template-rows: auto auto 1fr; column-gap: 24px; row-gap: 12px; padding: 16px 22px 16px 16px !important; border-radius: 26px !important; background: rgba(10, 14, 22, .38) !important; backdrop-filter: blur(14px) !important; border: 1px solid rgba(255, 255, 255, .14) !important; box-shadow: 0 10px 30px rgba(0, 0, 0, .35) !important; }
body.player-expanded .player-widget.expanded .album-art { grid-column: 1; grid-row: 1 / span 3; width: 100% !important; height: 100% !important; min-height: 0; border-radius: 20px !important; }
