body.player-expanded .player-widget.expanded .player-controls .play svg { width: 44px; height: 44px; }
body.player-expanded .player-widget.expanded .player-extra { display: contents; }
body.player-expanded .player-widget.expanded .player-vol { display: flex !important; grid-column: 2 / 4; grid-row: 2; align-items: center; gap: 14px; padding: 0; }
