body.player-expanded .player-widget.expanded .player-vol .ic svg { width: 26px; height: 26px; fill: currentColor; display: block; }
body.player-expanded .player-widget.expanded .player-vol-line { height: 12px; background: rgba(255, 255, 255, .22); }
