body.player-expanded .player-widget.expanded .player-vol-val { color: var(--text); font-size: 17px; }
body.player-expanded .player-widget.expanded .player-timeline { display: flex !important; grid-column: 2 / 4; grid-row: 3; align-items: stretch; min-height: 34px; }
