body.player-expanded .player-widget.expanded .eyebrow { font-size: 12px; letter-spacing: .14em; color: var(--muted); }
:root[data-theme="light"] body.player-expanded .player-widget.expanded { background: rgba(246, 248, 252, .58) !important; border-color: rgba(20, 40, 70, .12) !important; box-shadow: 0 10px 30px rgba(27, 38,64, .18) !important; color: #1b2230; }
:root[data-theme="light"] body.player-expanded .player-widget.expanded .player-vol-line { background: rgba(20, 40, 70, .14); }
:root[data-theme="light"] body.player-expanded .player-widget.expanded .player-tl-line .wv { background: rgba(20, 40, 70, .2); }
:root[data-theme="light"] body.player-expanded .player-widget.expanded .player-controls .play { background: rgba(31, 111, 214, .10) !important; border-color: #1f6fd6 !important; color: #1f6fd6 !important; }
:root[data-theme="light"] body.player-expanded .player-widget.expanded .player-controls button { color: #1b2230; }
:root[data-theme="light"] body.player-expanded .player-widget.expanded .player-vol .ic { color: #1b2230; }
/* Cover mode: wallpaper to the edges, no shade, no inset frame, no focus ring on the weather chip. */
body.player-expanded .dashboard { padding: 0 !important; }
body.player-expanded .hero-shade { display: none !important; }
body.player-expanded .weather-widget, body.player-expanded .weather-widget:focus, body.player-expanded .weather-widget:focus-visible { outline: none !important; }
:root[data-theme="light"] body.player-expanded .hero-clock { background: none !important; border: 0 !important; box-shadow: none !important; backdrop-filter: none !important; }
body.player-expanded .player-widget.expanded { grid-template-columns: clamp(150px, 17.3vw, 222px) minmax(0, 1fr) auto !important; }

/* ===== Home screen, as in the port of the mock: row 1 clock, weather, last trip; row 2 player; row 3 navigation, rings, car state. ===== */
.hero { display: flex; flex-direction: column; gap: 14px; }
.hero-bottom:not(.in-stage) { position: static !important; display: grid !important; grid-template-columns: 360px 300px minmax(0, 1fr); grid-template-rows: 112px 112px; gap: 14px; overflow: visible; padding: 0; order: 1; width: 100%; }
.hero-bottom:not(.in-stage) > .hero-clock { grid-column: 1; grid-row: 1; height: 112px !important; min-height: 0 !important; width: auto !important; flex: none !important; padding: 14px 18px !important; justify-content: center; }
.hero-bottom:not(.in-stage) > .hero-clock .clock { font-size: 66px; font-weight: 300; letter-spacing: -.04em; line-height: 1; }
.hero-bottom:not(.in-stage) > .hero-clock .date-row { display: block; margin-top: 4px; }
.hero-bottom:not(.in-stage) > .hero-clock .date { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: var(--muted); }
