.hero-bottom:not(.in-stage) > #weather-widget { grid-column: 2; grid-row: 1; height: 112px !important; min-height: 0 !important; width: auto !important; flex: none !important; padding: 14px 18px !important; }
.hero-bottom:not(.in-stage) > .hw-trip { grid-column: 3; grid-row: 1; height: 112px; min-height: 0; width: auto; padding: 14px 18px; }
.hero-bottom:not(.in-stage) > .player-widget { grid-column: 1 / span 3; grid-row: 2; height: 112px !important; min-height: 0 !important; width: auto !important; max-width: none !important; flex: none !important; padding: 12px 18px !important; }
.hero-bottom:not(.in-stage) .player-widget .album-art { width: 88px !important; height: 88px !important; flex: 0 0 88px; border-radius: 16px; }
.hero-bottom:not(.in-stage) .player-widget .track-title { font-size: 20px; }
body:not(.player-expanded) .player-widget .player-timeline { display: flex !important; flex: 1 1 260px; min-width: 0; }
body:not(.player-expanded) .player-widget .player-tl-line { display: flex; align-items: center; gap: 3px; height: 30px; background: none; overflow: visible; }
body:not(.player-expanded) .player-widget .player-tl-line .wv { height: 60%; background: rgba(255, 255, 255, .25); }
body:not(.player-expanded) .player-widget .player-tl-line .wv.on { background: var(--accent); }
body:not(.player-expanded) .player-widget .player-time, body:not(.player-expanded) .player-widget .player-vol { display: none !important; }
body:not(.player-expanded) .player-widget .player-controls { flex: 0 0 auto; }

/* Trip card, the same glass as the other cards. */
.hw-trip { pointer-events: auto; }
.hw-trip .hw-eb { text-align: center; cursor: pointer; }
.hw-trip .hw-body { display: flex; flex-direction: column; justify-content: center; flex: 1; gap: 6px; min-height: 0; }
.hw-trip-main { display: flex; align-items: baseline; gap: 6px; }
.hw-trip-main strong { font-size: 34px; font-weight: 500; line-height: 1; }
.hw-trip-main small { font-size: 14px; color: var(--muted); }
.hw-trip-stats { display: flex; justify-content: space-between; gap: 6px; }
.hw-trip-stats b { display: block; font-size: 17px; font-weight: 600; }
.hw-trip-stats span { font-size: 11px; color: var(--muted); white-space: nowrap; }
.hw-trip-empty { color: var(--muted); font-size: 14px; margin: auto; }

/* Middle column: fuel and battery, each in its own card. */
.hw-rings-col { display: flex; flex-direction: column; gap: 14px; min-width: 0; min-height: 0; pointer-events: auto; }
.hw-ring-card { flex: 1 1 0; min-height: 0; padding: 10px 14px; justify-content: center; }
.hw-ring-card .hw-rings, .hw-ring-card > .hw-ring { display: block; }
.hw-ring-card .hw-ring { display: grid; grid-template-columns: 76px minmax(0, 1fr); column-gap: 12px; align-items: center; width: 100%; }
.hw-ring-card .hw-ring svg { width: 76px; height: 76px; grid-column: 1; grid-row: 1; }
.hw-ring-card .hw-ring-val { top: 0; left: 0; width: 76px; height: 76px; justify-content: center; align-items: center; text-align: center; }
.hw-ring-card .hw-ring-val b { font-size: 17px; }
.hw-ring-card .hw-ring-sub { grid-column: 2; grid-row: 1; text-align: left; font-size: 13px; color: var(--muted); margin: 0; }

/* Navigation and car state cards: titles centred. Radar and speed live as before. */
.hero-widgets { position: static !important; display: grid !important; grid-template-columns: 560px 262px minmax(0, 1fr); grid-auto-rows: 166px; gap: 14px; height: auto !important; bottom: auto !important; left: auto !important; right: auto !important; order: 2; z-index: auto; pointer-events: none; }
.hero-widgets > .hw-nav { grid-column: 1; grid-row: 1; }
.hero-widgets > .hw-rings-col { grid-column: 2; grid-row: 1; }
.hero-widgets > .hw-state { grid-column: 3; grid-row: 1; }
.hero-widgets > .hw-compass { display: none !important; }
.hero-widgets > .hw-state { pointer-events: auto; }

/* Car-state tiles: icon, label and state word; no boxes. Tapping runs the action (home-tiles.js). */
.hw-state .hw-body { margin-top: 0; }
.hw-state .hw-chips { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 6px; height: 100%; align-items: start; padding-top: 6px; }
.hw-state .hw-tile { display: flex; flex-direction: column; align-items: center; gap: 4px; padding: 6px 2px; min-width: 0; min-height: 0; border: 0; border-radius: 14px; background: transparent; color: var(--text); font: inherit; cursor: pointer; -webkit-tap-highlight-color: transparent; }
.hw-state .hw-tile:active { background: rgba(255, 255, 255, .06); }
.hw-tile-icon { width: 26px; height: 26px; display: grid; place-items: center; color: var(--muted); }
.hw-tile-icon svg { width: 26px; height: 26px; }
.hw-tile-label { font-size: 13px; white-space: nowrap; color: var(--text); }
.hw-tile-value { font-style: normal; font-size: 11px; min-height: 14px; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
.hw-tile.open .hw-tile-icon, .hw-tile.open .hw-tile-value { color: #ff9d4d; }
.hw-tile.sent { background: rgba(111, 195, 250, .12); border-radius: 14px; }
.hw-tile.blocked { animation: tile-shake .35s linear 2; }
@keyframes tile-shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-4px); } 75% { transform: translateX(4px); } }
:root[data-theme="light"] .hw-tile-label { color: #1b2230; }
:root[data-theme="light"] .hw-tile.open .hw-tile-icon, :root[data-theme="light"] .hw-tile.open .hw-tile-value { color: #d9642b; }
/* Home port: the waveform bars replace the progress line (the fill stays for the scrub and the count). */
body:not(.player-expanded) .player-widget .player-tl-line > #track-line-fill { display: none; }
