body:not(.player-expanded) .player-widget .player-tl-line .wv { height: auto; align-self: center; }
body:not(.player-expanded) .player-widget .player-extra { display: flex !important; flex: 1 1 260px; min-width: 0; align-items: center; }
body:not(.player-expanded) .player-widget .player-timeline { flex: 1 1 0; min-width: 0; }
/* Home port player: cover, title, waveform in the middle, controls on the right. */
body:not(.player-expanded) .hero-bottom:not(.in-stage) > .player-widget { gap: 18px; }
