body:not(.player-expanded) .player-widget .player-controls { order: 3; margin-left: auto; }
body:not(.player-expanded) .player-widget .track-title { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
body:not(.player-expanded) .player-widget .track-progress { display: none; }
body:not(.player-expanded) .hero-bottom:not(.in-stage) > .hero-clock { justify-content: flex-start; padding-top: 16px !important; }
/* Top row: track pill, radar pill, in one centred row at the top edge (above the cards). */
#top-pills { position: fixed; top: 0; left: 50%; transform: translateX(-50%); z-index: 1000; display: flex; gap: 12px; align-items: flex-start; pointer-events: none; }
#top-pills > * { position: static !important; transform: none !important; left: auto !important; top: auto !important; margin: 0; }
