#top-pills #track-toast, #top-pills #radar-strip { border-top: 0; border-radius: 0 0 14px 14px; }
#top-pills #track-toast { height: 60px; width: auto; max-width: min(460px, 44vw); }
#top-pills #radar-strip:not([hidden]) { display: inline-flex; align-items: center; }
