/* Cover mode hides the home-port cards (navigation, rings, car state, trip); the cover has its own layout. */
body.player-expanded .hero-widgets, body.player-expanded .hw-trip, body.player-expanded .hw-rings-col { display: none !important; }

/* 10-day forecast sheet (long press on the weather). It had no styles before: a card over a dim layer. */
.forecast-sheet { position: fixed; inset: 0; z-index: 60; display: grid; place-items: center; background: rgba(0, 0, 0, .45); padding: 16px; }
.forecast-sheet[hidden] { display: none; }
.forecast-card { width: min(520px, 100%); max-height: calc(100vh - 32px); overflow: auto; background: var(--surface); color: var(--text); border: 1px solid rgba(255, 255, 255, .14); border-radius: 28px; padding: 18px 22px; box-shadow: 0 18px 50px rgba(0, 0, 0, .45); }
.forecast-card h3 { margin: 0 0 10px; font-size: 20px; font-weight: 600; }
.forecast-list { display: grid; gap: 6px; }
.forecast-row { display: grid; grid-template-columns: minmax(0, 1fr) 40px auto; align-items: center; gap: 10px; padding: 8px 4px; border-bottom: 1px solid rgba(255, 255, 255, .08); font-size: 17px; }
.forecast-row:last-child { border-bottom: 0; }
.forecast-day { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.forecast-icon { text-align: center; font-size: 22px; color: var(--accent); }
.forecast-temp { white-space: nowrap; color: var(--muted); }
