/* Home port, fitted to the car screen height (about 720 px): top row clock / weather / trip, the player under them, then navigation, fuel and battery, car state. */
.hero-bottom:not(.in-stage) { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) minmax(0, 1.6fr) !important; grid-template-rows: 124px 132px !important; }
.hero-bottom:not(.in-stage) > .hero-clock, .hero-bottom:not(.in-stage) > #weather-widget, .hero-bottom:not(.in-stage) > .hw-trip { height: 124px !important; }
.hero-bottom:not(.in-stage) > .hero-clock .clock { font-size: 72px; }
.hero-bottom:not(.in-stage) > .player-widget { height: 132px !important; grid-column: 1 / span 3; }
.hero-bottom:not(.in-stage) .player-widget .album-art { width: 108px !important; height: 108px !important; flex: 0 0 108px; }
.hero-bottom:not(.in-stage) .player-widget .track-title { font-size: 24px; }
.hero-widgets { grid-template-columns: minmax(0, 1.6fr) minmax(0, 1fr) minmax(0, 2fr) !important; grid-auto-rows: 150px !important; }

/* Home port, reference screen: top row car state / navigation / compass; middle row clock / weather / player. Rings hidden. */
body.home-port .hero-widgets { display: none !important; }
body.home-port #hw-rings-col { display: none !important; }
body.home-port .hw-trip { display: none !important; }
.hero-bottom:not(.in-stage) { display: grid !important; grid-template-columns: repeat(20, minmax(0, 1fr)) !important; grid-template-rows: 208px 208px !important; gap: 14px !important; }
.hero-bottom:not(.in-stage) > .hw-state { grid-column: 1 / span 10; grid-row: 1; height: 208px !important; }
.hero-bottom:not(.in-stage) > .hw-nav { grid-column: 11 / span 8; grid-row: 1; height: 208px !important; }
.hero-bottom:not(.in-stage) > .hw-compass { grid-column: 19 / span 2; grid-row: 1; height: 208px !important; }
.hero-bottom:not(.in-stage) > .hero-clock { grid-column: 1 / span 5; grid-row: 2; height: 208px !important; }
.hero-bottom:not(.in-stage) > #weather-widget { grid-column: 6 / span 5; grid-row: 2; height: 208px !important; }
.hero-bottom:not(.in-stage) > .player-widget { grid-column: 11 / span 10; grid-row: 2; height: 208px !important; }

/* Media player: a plain progress bar instead of the waveform bars (home and cover). */
