// Компас: курс берётся из GPS-трека (camera-alerts.js). Без курса — только прочерк.
const COMPASS_POINTS = ["С", "СВ", "В", "ЮВ", "Ю", "ЮЗ", "З", "СЗ"];
function renderCompass() {
