// Меню слота по долгому нажатию: «Заменить», «Переставить» (режим перестановки) и «Удалить» (только у занятого слота).
function openSlotMenu(index, element) {
  document.querySelectorAll(".slot-menu-backdrop").forEach(node => node.remove());
  const filled = !!(state.slots[index] && state.slots[index].type !== "empty");
  const backdrop = document.createElement("div");
  backdrop.className = "slot-menu-backdrop";
  backdrop.innerHTML = `<div class="slot-menu" role="menu" aria-label="Слот">` +
    `<button type="button" role="menuitem" data-act="replace">Заменить</button>` +
    `<button type="button" role="menuitem" data-act="move">Переставить</button>` +
    (filled ? `<button type="button" role="menuitem" class="danger" data-act="delete">Удалить</button>` : "") +
    `</div>`;
  document.body.appendChild(backdrop);
  const menu = backdrop.querySelector(".slot-menu");
  const rect = element.getBoundingClientRect();
  const width = menu.offsetWidth || 200;
  const height = menu.offsetHeight || 150;
  const left = Math.max(8, Math.min(window.innerWidth - width - 8, rect.left + rect.width / 2 - width / 2));
  const top = rect.bottom + 8 + height <= window.innerHeight ? rect.bottom + 8 : Math.max(8, rect.top - height - 8);
  menu.style.left = left + "px";
  menu.style.top = top + "px";
  backdrop.addEventListener("click", event => {
    if (event.target === backdrop) { backdrop.remove(); return; }
    const button = event.target.closest("[data-act]");
    if (!button) return;
    const act = button.dataset.act;
    backdrop.remove();
    if (act === "replace") openPicker(index);
    else if (act === "move") enterSlotOrder();
    else if (act === "delete") removeSlot(index);
  });
}

files.tracktoast.js:
// Уведомление о смене песни: пилюля сверху (обложка, название, исполнитель), 6 секунд, по нажатию открывает музыку.
// Полоса радара (если радар активен) занимает то же место сверху: тогда пилюля песни уходит.
let lastTrackKey = null;
let trackToastTimer = null;
let lastToastOpenAt = 0;
const TIGGO_MUSIC_APP = "ru.yandex.music";

// One row at the top centre for the track pill, the radar pill and any other top notice.
function topPillsElement() {
  let box = document.getElementById("top-pills");
  if (!box) {
    box = document.createElement("div");
    box.id = "top-pills";
    document.body.appendChild(box);
  }
  return box;
}

function trackToastElement() {
  let toast = document.getElementById("track-toast");
  if (toast) return toast;
  toast = document.createElement("div");
  toast.id = "track-toast";
  toast.setAttribute("role", "status");
  toast.innerHTML = '<span class="tt-art" aria-hidden="true"></span><div class="tt-text"><strong class="tt-title"></strong><span class="tt-artist"></span></div>';
  const open = () => {
    const now = Date.now();
    if (now - lastToastOpenAt < 500) return;
    lastToastOpenAt = now;
    hideTrackToast();
    if (bridge.has("runApp")) bridge.runApp(TIGGO_MUSIC_APP);
  };
  toast.addEventListener("pointerdown", open);
  toast.addEventListener("click", open);
  topPillsElement().appendChild(toast);
  return toast;
}

function showTrackToast(title, artist, picture) {
  const toast = trackToastElement();
  toast.querySelector(".tt-title").textContent = title;
  toast.querySelector(".tt-artist").textContent = artist || "";
  const url = typeof musicArtworkUrl === "function" ? musicArtworkUrl(picture) : "";
  toast.querySelector(".tt-art").style.backgroundImage = url ? `url("${url}")` : "";
  toast.classList.add("show");
  clearTimeout(trackToastTimer);
  trackToastTimer = setTimeout(hideTrackToast, 6000);
}

function hideTrackToast() {
  clearTimeout(trackToastTimer);
  const toast = document.getElementById("track-toast");
  if (toast) toast.classList.remove("show");
}

// Called on every musicInfo message. The first message after start-up only records the track, so nothing pops up on launch.
function noteTrackChange(title, artist, picture) {
  if (!title) return;
  const key = `${title}|${artist}`;
  if (lastTrackKey === null) { lastTrackKey = key; return; }
  if (key === lastTrackKey) return;
  lastTrackKey = key;
  showTrackToast(title, artist, picture);
}

// Distance to the radar for the top strip: metres under a km, then km with one decimal.
function radarDistText(m) {
  if (!Number.isFinite(m)) return "";
  return m < 1000 ? `${Math.round(m / 10) * 10} м` : `${(m / 1000).toFixed(1)} км`;
}

// Radar strip at the top: shown while the car reports an active radar (window.navWarning.hud).
function radarStripElement() {
  let strip = document.getElementById("radar-strip");
  if (strip) return strip;
  strip = document.createElement("div");
  strip.id = "radar-strip";
  strip.hidden = true;
  strip.innerHTML = '<span class="ns-radar"></span>';
  topPillsElement().appendChild(strip);
  return strip;
}

function syncRadarStrip() {
  const hud = window.navWarning && window.navWarning.hud;
  const strip = radarStripElement();
  strip.hidden = !hud;
  document.body.classList.toggle("radar-only", !!hud);
  if (hud) {
    const limit = hud.limit ? ` ${hud.limit}` : "";
    const dist = radarDistText(hud.dist);
    strip.querySelector(".ns-radar").textContent = `Радар${limit}${dist ? " · " + dist : ""}`;
  }
}
setInterval(syncRadarStrip, 1000);

files.rings.js:
// Кольца топлива и АКБ в карточке состояния автомобиля (как в сборке Андрея Грачева): цифра в центре, подпись снизу.
// Топливо: литры из процента бака (объём бака 60 л, как в config и trips.js). АКБ: вольты, шкала 9–16 В.
const RING_TANK_LITERS = 60;
const RING_CIRC = 2 * Math.PI * 36;

function ringHtml(fraction, value, unit, sub) {
  const f = Math.max(0, Math.min(1, fraction || 0));
  return `<div class="hw-ring"><svg viewBox="0 0 84 84" aria-hidden="true"><circle class="hw-ring-bg" cx="42" cy="42" r="36"/>` +
    `<circle class="hw-ring-fg" cx="42" cy="42" r="36" stroke-dasharray="${(RING_CIRC * f).toFixed(1)} ${RING_CIRC.toFixed(1)}"/></svg>` +
    `<div class="hw-ring-val"><b>${value}</b><small>${unit}</small></div><div class="hw-ring-sub">${sub}</div></div>`;
}

function renderRings() {
  // Two stacked cards in the middle column of the home screen: fuel and battery.
  const box = document.getElementById("hw-rings-col");
  if (!box) return;
  const fuel = typeof tiggoState !== "undefined" && typeof tiggoState.fuel === "number" ? tiggoState.fuel : null;
  const volts = typeof tiggoState !== "undefined" && typeof tiggoState.voltage === "number" ? tiggoState.voltage : null;
  const comma = n => n.toFixed(1).replace(".", ",");
  const fuelRing = fuel === null
    ? ringHtml(0, "—", "литров", "нет данных")
    : ringHtml(fuel / 100, comma(fuel * RING_TANK_LITERS / 100), "литров", `${Math.round(fuel)}% бака из ${RING_TANK_LITERS} л`);
  const batRing = volts === null
    ? ringHtml(0, "—", "вольт", "нет данных")
    : ringHtml((volts - 9) / 7, comma(volts), "вольт", volts >= 12.4 && volts <= 15.5 ? "норма 12,4–15,5 В" : "вне нормы");
  box.innerHTML = `<section class="hw-card hw-ring-card">${fuelRing}</section><section class="hw-card hw-ring-card">${batRing}</section>`;
}
setInterval(renderRings, 1000);
renderRings();

files.waveform.js:
// Волновая полоса плеера: 48 столбиков вместо прямой линии. Пройденная часть трека подсвечивается акцентом.
// Высоты столбиков фиксированы по номеру (это оформление, а не данные трека); прогресс берётся из #track-line-fill.
(function () {
  const COUNT = 48;
  function build() {
    const line = document.querySelector(".player-tl-line");
    if (!line || line.querySelector(".wv")) return;
    for (let i = 0; i < COUNT; i++) {
      const bar = document.createElement("i");
      bar.className = "wv";
      const h = 0.35 + 0.65 * Math.abs(Math.sin(i * 12.9898) * 43758.5453 % 1);
      bar.style.height = Math.round(h * 30) + "px";
      line.appendChild(bar);
    }
  }
  function paint() {
    const fill = document.getElementById("track-line-fill");
    if (!fill) return;
    const pct = parseFloat(fill.style.width) || 0;
    const lit = Math.round((pct / 100) * COUNT);
    document.querySelectorAll(".player-tl-line .wv").forEach((bar, i) => bar.classList.toggle("on", i < lit));
  }
  build();
  setInterval(() => { build(); paint(); }, 400);
})();

